import{_ as e,c as l,o as a,a3 as n}from"./chunks/framework.BusRvirq.js";const h=JSON.parse('{"title":"선금(선급금) 신청서 및 사용계획서","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/04_Advance_Payment_template.html"}]]},"headers":[],"relativePath":"public/templates/04_Advance_Payment_template.md","filePath":"public/templates/04_Advance_Payment_template.md","lastUpdated":1790810085000}'),d={name:"public/templates/04_Advance_Payment_template.md"};function r(i,t,s,g,o,x){return a(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="선금-선급금-신청서-및-사용계획서" tabindex="-1">선금(선급금) 신청서 및 사용계획서 <a class="header-anchor" href="#선금-선급금-신청서-및-사용계획서" aria-label="Permalink to “선금(선급금) 신청서 및 사용계획서”">​</a></h1><p>국가를 당사자로 하는 계약에 관한 법률 시행령 제56조 및 정부 입찰·계약 집행기준 제34조(선금의 지급 등), 관련 민간 용역계약서 규정에 의거하여 아래와 같이 선금 지급을 신청합니다.</p><hr><h3 id="_1-계약-기본-사항" tabindex="-1">1. 계약 기본 사항 <a class="header-anchor" href="#_1-계약-기본-사항" aria-label="Permalink to “1. 계약 기본 사항”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명 (계약건명)</strong></td><td style="text-align:left;">[공식 계약명]</td></tr><tr><td style="text-align:left;"><strong>계약 번호</strong></td><td style="text-align:left;">[계약서상 계약번호]</td></tr><tr><td style="text-align:left;"><strong>계약 체결 일자</strong></td><td style="text-align:left;">202 년 월 일</td></tr><tr><td style="text-align:left;"><strong>총 계약 기간</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일</td></tr><tr><td style="text-align:left;"><strong>총 계약 금액</strong></td><td style="text-align:left;">일금 [ ] 원 (VAT 포함)</td></tr><tr><td style="text-align:left;"><strong>신청자 (계약상대자)</strong></td><td style="text-align:left;">주식회사 엠파시 (대표이사: [ ])</td></tr></tbody></table><hr><h3 id="_2-선금-신청-내역" tabindex="-1">2. 선금 신청 내역 <a class="header-anchor" href="#_2-선금-신청-내역" aria-label="Permalink to “2. 선금 신청 내역”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:center;">금액 (원)</th><th style="text-align:center;">비율 (%)</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>총 계약금액</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">100 %</td><td style="text-align:left;">VAT 포함</td></tr><tr><td style="text-align:left;"><strong>금회 선금 신청액</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ] %</td><td style="text-align:left;">계약금의 최대 70% 이내 신청</td></tr><tr><td style="text-align:left;"><strong>선금 공제 후 잔여액</strong></td><td style="text-align:center;">[ ]</td><td style="text-align:center;">[ ] %</td><td style="text-align:left;">기성금 및 준공금 수령 시 정산</td></tr></tbody></table><ul><li><strong>선금 입금 전용 계좌</strong>: <ul><li>은행명: [ ] 은행</li><li>계좌번호: [ ]</li><li>예금주: 주식회사 엠파시 (선금 관리 전용 계좌)</li></ul></li></ul><hr><h3 id="_3-선금-사용-계획서-비목별-집행-계획" tabindex="-1">3. 선금 사용 계획서 (비목별 집행 계획) <a class="header-anchor" href="#_3-선금-사용-계획서-비목별-집행-계획" aria-label="Permalink to “3. 선금 사용 계획서 (비목별 집행 계획)”">​</a></h3><p>선금은 본 사업의 원활한 수행을 위한 직접 인건비 및 필수 자재·소프트웨어 구매 비용에 한하여 우선 집행되며, 타 용도로 전용되지 않습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">비목 구분</th><th style="text-align:left;">세부 집행 내역</th><th style="text-align:center;">예정 금액 (원)</th><th style="text-align:center;">집행 예정 시기</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>직접 인건비</strong></td><td style="text-align:left;">핵심 투입 개발 인력(PM, 아키텍트, 백엔드/프론트엔드) 급여 및 용역비</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">202 . 월 ~ 월</td><td style="text-align:left;">계약 초기 3개월분</td></tr><tr><td style="text-align:left;"><strong>인프라/클라우드</strong></td><td style="text-align:left;">개발/테스트용 GPU 서버 및 클라우드 호스팅 선납 비용</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">202 . 월</td><td style="text-align:left;">초기 환경 구성비</td></tr><tr><td style="text-align:left;"><strong>외부 솔루션 라이선스</strong></td><td style="text-align:left;">필수 미들웨어, RDBMS, 보안 솔루션 도입 선지급금</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">202 . 월</td><td style="text-align:left;">선급 라이선스</td></tr><tr><td style="text-align:left;"><strong>하도급 대금</strong></td><td style="text-align:left;">사전 승인된 하도급 협력사 선금 지급분</td><td style="text-align:center;">[ ]</td><td style="text-align:center;">202 . 월</td><td style="text-align:left;">하도급 선금 연동</td></tr><tr><td style="text-align:left;"><strong>합계</strong></td><td style="text-align:left;"><strong>선금 신청 총액과 일치</strong></td><td style="text-align:center;"><strong>[ ]</strong></td><td style="text-align:center;">-</td><td style="text-align:left;">-</td></tr></tbody></table><hr><h3 id="_4-선금-수령-및-관리-확약-사항" tabindex="-1">4. 선금 수령 및 관리 확약 사항 <a class="header-anchor" href="#_4-선금-수령-및-관리-확약-사항" aria-label="Permalink to “4. 선금 수령 및 관리 확약 사항”">​</a></h3><ol><li>당사는 지급받은 선금을 본 계약의 목적 달성을 위한 용도 이외에 다른 목적(타 사업 투입, 회사 운영비 전용 등)으로 사용하지 않겠습니다.</li><li>선금 집행 내역에 대하여 발주처의 증빙 제출 요구(입금표, 세금계산서, 이체확인증 등)가 있을 경우 지체 없이 제출하겠습니다.</li><li>계약 해제, 과업 변경 등으로 인한 선금 반환 사유 발생 시, 미정산 잔액에 대하여 법정 이자를 가산하여 즉시 반환하겠습니다.</li><li>하도급 업체가 있는 경우, 선금을 수령한 날로부터 15일 이내에 하수급인에게 해당 비율만큼 선금을 현금으로 지급하고 그 지급 내역을 발주처에 통보하겠습니다.</li></ol><hr><h3 id="_5-첨부-서류" tabindex="-1">5. 첨부 서류 <a class="header-anchor" href="#_5-첨부-서류" aria-label="Permalink to “5. 첨부 서류”">​</a></h3><ol><li>선금급 지급보증서 (SGI서울보증 또는 소프트웨어공제조합 발행) 1부</li><li>선금 사용계획서 세부 산출내역 1부</li><li>선금 관리 통장 사본 1부</li><li>국세 및 지방세 완납증명서 각 1부</li><li>4대 사회보험 완납증명서 1부</li></ol><hr><p>위와 같이 선금을 신청하오니 검토 후 지급하여 주시기 바랍니다.</p><p><strong>신청일자: 202 년 월 일</strong></p><p><strong>신청인 (계약상대자)</strong></p><ul><li>상호명: 주식회사 엠파시</li><li>주소: [ ]</li><li>대표이사: [ ] (인)</li></ul><p><strong>귀하 (발주처 대표자 / 계약담당관)</strong></p>',25)])])}const c=e(d,[["render",r]]);export{h as __pageData,c as default};
